ROOT.scriptdef:
  SET NOCOUNT ON;DECLARE @INDSQL VARCHAR(max)
  SET @INDSQL = '
CREATE NONCLUSTERED INDEX KeyBnk ON CDN.CDCLoginy
             (
             CDCL_BnkNumer
             )
ON '+ISNULL((SELECT QUOTENAME(fgName) FROM #XLIndexesFileGroups WHERE indName = 'KeyBnk'),QUOTENAME('PRIMARY'))
  EXEC(@INDSQL);SET NOCOUNT OFF;
;

